Add({
	id = "the-stockade",
	title = "The Stockade",
	aliases = { "Stockade", "Stormwind Stockade" },
	faction = "Alliance",
	continent = "Eastern Kingdoms",
	zone = "The Stockade",
	unlock = {
		{ type = "zone" },
